{
  "$schema": "https://opencode.ai/config.json",
  "model": "minimax-coding-plan/MiniMax-M3",
  "permission": "allow",
  "default_agent": "architect",
  "instructions": ["~/sync/code/ai-memory/direction.md"],
  "watcher": {
    "ignore": [
      "node_modules/**",
      "dist/**",
      ".git/**",
      "*.log"
    ]
  }
}

{
  "model": "some/model",
  "mcp": {
    "lookup": {
      "type": "local",
      "command": [
        "~/bin/lookup",
        "--stdio"
      ],
      "environment": {
        "TOKEN_FILE": "~/token"
      },
      "enabled": true
    },
    "paused": {
      "type": "local",
      "command": [
        "paused-server"
      ],
      "enabled": false
    },
    "web": {
      "type": "local",
      "command": [
        "npx",
        "web-mcp"
      ],
      "enabled": true,
      "timeout": 5
    }
  }
}

{
  "model": "some/model"
}

{
  "name": "dsh-profile-web",
  "private": true,
  "dependencies": {},
  "dsh": {
    "profile": {
      "bundles": [
        "@deepseek-ai/dsh-base",
        "@deepseek-ai/dsh-web-app"
      ]
    }
  }
}
